CREATE OR REPLACE FUNCTION public.pick_refusal(p_world uuid, p_x integer, p_y integer, p_now timestamp with time zone DEFAULT now())
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare w water_plant; v_state text[]; v_name text;
begin
  select * into w from water_plant where world_id = p_world and x = p_x and y = p_y;
  if not found then return 'Nothing planted here.'; end if;
  if not has_water(p_world, p_x, p_y) then return 'No water: dormant until it returns.'; end if;
  v_name := water_plant_word(w.kind);
  v_state := string_to_array(water_plant_state(w.kind, w.planted_at, w.picked_at, p_now), '|');
  if v_state[2] = 'rooting' then
    return 'Not rooted yet: roots ' || water_rooting_said() || ' after planting.';
  end if;
  if v_state[4] = 'none' then return upper(left(v_name, 1)) || substr(v_name, 2) || ': ' || water_year_says(w.kind) || '. Now: ' || v_state[1] || '.'; end if;
  if v_state[5] = 'bare' then
    return case when v_state[4] = 'seed' then 'Seed head' else 'Flower' end
        || ' already picked this ' || v_state[1] || '. Next one next season.';
  end if;
  return null;
end $function$
